'use strict';

// Host-side contract check for src/pipeline.js. The worker protocol owns
// stdout and stderr, so this script fails if loading or running the module
// writes anything through the console. It also pins the exact shapes the
// host expects from each function.

const assert = require('node:assert');

const leaked = [];
const original = {};
for (const m of ['log', 'info', 'warn', 'error', 'debug', 'trace']) {
  original[m] = console[m];
  console[m] = function () {
    leaked.push(m + ': ' + Array.prototype.join.call(arguments, ' '));
  };
}

const p = require('./src/pipeline.js');

const lines = ['signup,3', '', 'refund,-2', ' signup,1 ', 'oops', 'click,notanumber'];
const snapshot = lines.slice();

const parsed = p.parseEvents(lines);
assert.deepStrictEqual(parsed.events, [
  { name: 'signup', value: 3 },
  { name: 'refund', value: -2 },
  { name: 'signup', value: 1 },
]);
assert.deepStrictEqual(parsed.bad, ['oops', 'click,notanumber']);

const s = p.summarize(parsed.events);
assert.deepStrictEqual(s.totals, { signup: 4 });
assert.strictEqual(s.count, 2);
assert.deepStrictEqual(s.negatives, [{ name: 'refund', value: -2 }]);

const report = p.runPipeline(lines);
assert.deepStrictEqual(report.totals, { signup: 4 });
assert.strictEqual(report.count, 2);
assert.strictEqual(report.dropped, 3);
assert.deepStrictEqual(report.issues, {
  bad: ['oops', 'click,notanumber'],
  negatives: [{ name: 'refund', value: -2 }],
});

assert.deepStrictEqual(lines, snapshot, 'pipeline must not mutate its input');

for (const m of Object.keys(original)) { console[m] = original[m]; }

if (leaked.length > 0) {
  console.error('QUIET CHECK FAILED: the pipeline wrote to the console:');
  for (const entry of leaked) { console.error('  ' + entry); }
  process.exit(1);
}

console.log('smoke ok: ' + JSON.stringify(report));

