'use strict';
const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const p = require('./src/pipeline.js');

test('parseEvents splits good and bad lines', () => {
  const out = p.parseEvents([' a,1', 'b,2.5', '', 'nope', 'c,x', 'd,-4']);
  assert.deepStrictEqual(out.events, [
    { name: 'a', value: 1 },
    { name: 'b', value: 2.5 },
    { name: 'd', value: -4 },
  ]);
  assert.deepStrictEqual(out.bad, ['nope', 'c,x']);
});

test('summarize totals non-negatives and collects negatives', () => {
  const out = p.summarize([
    { name: 'a', value: 1 },
    { name: 'a', value: 2 },
    { name: 'b', value: 0 },
    { name: 'c', value: -3 },
  ]);
  assert.deepStrictEqual(out.totals, { a: 3, b: 0 });
  assert.strictEqual(out.count, 3);
  assert.deepStrictEqual(out.negatives, [{ name: 'c', value: -3 }]);
});

test('runPipeline reports drops as values, without mutating input', () => {
  const lines = ['a,1', 'junk', 'b,-2'];
  const snapshot = lines.slice();
  const report = p.runPipeline(lines);
  assert.deepStrictEqual(report.totals, { a: 1 });
  assert.strictEqual(report.count, 1);
  assert.strictEqual(report.dropped, 2);
  assert.deepStrictEqual(report.issues, { bad: ['junk'], negatives: [{ name: 'b', value: -2 }] });
  assert.deepStrictEqual(lines, snapshot);
});

test('pipeline never writes to the console or stdio', () => {
  const leaked = [];
  const original = {};
  for (const m of ['log', 'info', 'warn', 'error', 'debug', 'trace']) {
    original[m] = console[m];
    console[m] = (...a) => { leaked.push(m + ': ' + a.join(' ')); };
  }
  const outWrite = process.stdout.write;
  const errWrite = process.stderr.write;
  process.stdout.write = (chunk) => { leaked.push('stdout: ' + chunk); return true; };
  process.stderr.write = (chunk) => { leaked.push('stderr: ' + chunk); return true; };
  try {
    p.runPipeline(['x,1', 'broken', 'y,-9', 'z,notanumber']);
  } finally {
    for (const m of Object.keys(original)) { console[m] = original[m]; }
    process.stdout.write = outWrite;
    process.stderr.write = errWrite;
  }
  assert.deepStrictEqual(leaked, []);
});

test('source stays silent and pure', () => {
  const raw = fs.readFileSync(path.join(__dirname, 'src', 'pipeline.js'), 'utf8');
  const src = raw.split('\n').map((l) => l.replace(/\/\/.*$/, '')).join('\n');
  assert.ok(!/console\s*[.[]/.test(src), 'no console calls in src/pipeline.js');
  assert.ok(!/process\s*\.\s*std(out|err)/.test(src), 'no direct stdout or stderr writes');
  assert.ok(!/Math\s*\.\s*random|Date\s*\.\s*now|new\s+Date\b/.test(src), 'no clocks or randomness');
});

