'use strict';

// Runs inside the ingest worker. stdout and stderr carry the worker line
// protocol, so this module must stay silent and side-effect free: report
// problems by returning them as values.

function parseEvents(lines) {
  const events = [];
  const bad = [];
  for (const raw of lines) {
    const line = String(raw).trim();
    if (line === '') { continue; }
    const at = line.indexOf(',');
    if (at < 1) { bad.push(raw); continue; }
    const name = line.slice(0, at).trim();
    const value = Number(line.slice(at + 1).trim());
    if (name === '' || !Number.isFinite(value)) { bad.push(raw); continue; }
    events.push({ name: name, value: value });
  }
  return { events: events, bad: bad };
}

function summarize(events) {
  const totals = {};
  const negatives = [];
  let count = 0;
  for (const ev of events) {
    if (ev.value < 0) {
      negatives.push({ name: ev.name, value: ev.value });
      continue;
    }
    totals[ev.name] = (totals[ev.name] || 0) + ev.value;
    count = count + 1;
  }
  return { totals: totals, count: count, negatives: negatives };
}

function runPipeline(lines) {
  const parsed = parseEvents(lines);
  const summary = summarize(parsed.events);
  return {
    totals: summary.totals,
    count: summary.count,
    dropped: parsed.bad.length + summary.negatives.length,
    issues: { bad: parsed.bad, negatives: summary.negatives },
  };
}

module.exports = { parseEvents: parseEvents, summarize: summarize, runPipeline: runPipeline };
